using System;using System.Collections.Generic;using System.Drawing;using System.Linq;namespace Mapping{    /// <summary>    ///     /// </summary>    public class BinDefinitionCollection    {        private readonly BinCodeMap _binCodeMap;        private readonly Dictionary<ushort, BinDefinition> _binDefinitions;        /// <summary>        ///         /// </summary>        /// <param name="binCodeMap"></param>        public BinDefinitionCollection(BinCodeMap binCodeMap)        {            if (binCodeMap is null)            {                throw new ArgumentNullException(nameof(binCodeMap), "Argument binCodeMap must not been null for BinDefinitionCollection.ctor");            }            this._binCodeMap = binCodeMap;            this._binDefinitions = new Dictionary<ushort, BinDefinition>();        }        public BinDefinition this[ushort binCode]        {            get            {                BinDefinition binDefinition;                bool succ = this._binDefinitions.TryGetValue(binCode, out binDefinition);                if (!succ)                {                    return null;                }                return binDefinition;            }        }        public void Add(BinDefinition binDefinition)        {            if (binDefinition is null)            {                throw new ArgumentNullException(nameof(binDefinition));            }            this._binDefinitions[binDefinition.BinCode] = binDefinition;        }        public void Add(ushort binCode, ushort binCount, bool work)        {            var bd = new BinDefinition(this._binCodeMap, binCode, binCount, work);            this.Add(bd);        }        public void Add(ushort binCode, ushort binCount, string binDescription, string binQuality, bool work, Color color)        {            var bd = new BinDefinition(this._binCodeMap, binCode, binCount, binDescription, binQuality, work, color);            this.Add(bd);        }        public void AddRange(IEnumerable<BinDefinition> binDefinitions)        {            foreach (var binDefinition in binDefinitions)            {                this.Add(binDefinition);            }        }        public void Remove(BinDefinition binDefinition)        {            if (binDefinition != null)            {                this._binDefinitions.Remove(binDefinition.BinCode);            }        }        public void RemoveAll(Func<BinDefinition, bool> predicate)        {            foreach (var bd in this._binDefinitions.Values)            {                if (predicate(bd))                {                    this.Remove(bd);                }            }        }        public void Clear()        {            this._binDefinitions.Clear();        }    }}